// A request flows: Client -> [SecurityFilterChain] -> DispatcherServlet -> Controller.
//
//   1) Authentication: a filter reads credentials, the AuthenticationManager
//      verifies them, and the Authentication is stored in SecurityContext.
//   2) Authorization: an authorization filter + method security decide
//      whether the authenticated principal may do this.

// Configure the chain (Spring Security 6 / Lambda DSL):
@Configuration
@EnableMethodSecurity                    // enables @PreAuthorize on methods
class Security {
    @Bean
    SecurityFilterChain chain(HttpSecurity http) throws Exception {
        return http
            .authorizeHttpRequests(a -> a
                .requestMatchers("/public/**").permitAll()
                .requestMatchers("/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated())
            .formLogin(Customizer.withDefaults())     // auth filter (form)
            .csrf(Customizer.withDefaults())           // CSRF protection filter
            .build();
    }
    @Bean
    PasswordEncoder encoder() { return new BCryptPasswordEncoder(); }   // never plain
}

// Method-level authorization — the principal is already authenticated.
@PreAuthorize("hasRole('ADMIN')")
public void delete(String userId) { /* only an ADMIN reaches here */ }
//   The Authentication (who) lives in SecurityContextHolder.getContext().
